return {
  reload: {
    hook: "onEvent",
    eventType: "turnEnd",
    promptOnPlayer: async (H, actor) => {
      const shotguns = actor.items.filter(item => item.type === "weapon" && H.weapon.isType(item, "Shotgun"));
      if (!shotguns.length || shotguns.some(weapon => weapon.system.loaded !== false)) return false;
      const resolve = actor.system.health.resolve.value;
      const wounds = actor.system.health.wounds.value;
      if (resolve <= 0 && wounds <= 0) {
        ui.notifications.warn("Hungry: no Resolve or Wounds to spend.");
        return false;
      }
      const options = [];
      if (resolve > 0) options.push({ value: "resolve", label: "Spend Resolve" });
      if (wounds > 0) options.push({ value: "wound", label: "Spend Wound" });
      const choice = await H.ask.one({
        title: "Hungry", hint: "Shotgun is Empty. Spend 1 Resolve or 1 Wound to Reload.",
        options, buttonChoices: true, cancelLabel: null,
      }) ?? options[0].value;
      await H.resource.adjust(actor, choice === "resolve" ? { resolve: -1 } : { wounds: -1 });
      await H.chat.post(`${actor.name} pays the price and reloads (Hungry).`, actor);
      await H.actions.reload(actor);
      return true;
    },
  },
};
